class Solution {
    public ListNode removeElements(ListNode head, int val) {
        List<Integer> vals = new ArrayList<>();
        ListNode cur = head;
        while (cur != null) {
            if (cur.val != val) vals.add(cur.val);
            cur = cur.next;
        }
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        for (int v : vals) {
            tail.next = new ListNode(v);
            tail = tail.next;
        }
        return dummy.next;
    }
}

