class Solution {
    public ListNode rotateRight(ListNode head, int k) {
        if (head == null || head.next == null || k == 0) return head;
        int len = 0;
        ListNode cur = head;
        while (cur != null) { len++; cur = cur.next; }
        k = k % len;
        for (int r = 0; r < k; r++) {
            ListNode prev = null;
            ListNode last = head;
            while (last.next != null) {
                prev = last;
                last = last.next;
            }
            prev.next = null;
            last.next = head;
            head = last;
        }
        return head;
    }
}

