class Solution {
    public ListNode reverseBetween(ListNode head, int left, int right) {
        List<Integer> vals = new ArrayList<>();
        ListNode cur = head;
        int idx = 1;
        while (cur != null) {
            if (idx >= left && idx <= right) vals.add(cur.val);
            idx++;
            cur = cur.next;
        }
        Collections.reverse(vals);
        cur = head;
        idx = 1;
        int vIdx = 0;
        while (cur != null) {
            if (idx >= left && idx <= right) cur.val = vals.get(vIdx++);
            idx++;
            cur = cur.next;
        }
        return head;
    }
}

class Solution {
    public ListNode reverseBetween(ListNode head, int left, int right) {
        ListNode dummy = new ListNode(0, head);
        ListNode prev = dummy;
        for (int i = 0; i < left - 1; i++) prev = prev.next;
        ListNode cur = prev.next;
        for (int i = 0; i < right - left; i++) {
            ListNode move = cur.next;
            cur.next = move.next;
            move.next = prev.next;
            prev.next = move;
        }
        return dummy.next;
    }
}

